let cachedKey = "";
let cachedPath = "";

function offsetAt(schedule, timestamp) {
    let offset = schedule[0];
    for (let index = 1; index < schedule.length; index += 2) {
        if (timestamp < schedule[index])
            break;
        offset = schedule[index + 1];
    }
    return offset;
}

function pathForOffset(offsetSeconds, timestamp) {
    const wantedOffset = Math.round(Number(offsetSeconds) || 0);
    const instant = Number(timestamp) || Date.now();
    const key = wantedOffset + ":" + Math.floor(instant / 60000);
    if (key === cachedKey)
        return cachedPath;

    let path = "";
    for (const timezone in PATHS) {
        if (offsetAt(OFFSET_SCHEDULES[timezone], instant) === wantedOffset)
            path += PATHS[timezone];
    }
    cachedKey = key;
    cachedPath = path;
    return path;
}
